const LOTS: Lot[] = [
  { n: '12', artist: 'Ilse Brandt', life: 'b. 1951', title: 'Harbour at Dusk', year: '1998', medium: 'oil on canvas', dims: '120 × 160 cm (47¼ × 63 in.)', sign: 'signed, titled and dated 1998 on the reverse', est: '£80,000 – 120,000', prov: ['The artist', 'Galerie Nord, Hamburg, 1999', 'Private collection, Edinburgh, acquired from the above in 2003'], lit: 'I. Brandt, Light and Water, Hamburg, 2002, p. 88, illustrated in colour', essay: 'Painted the year Brandt moved from Hamburg to the Baltic coast, Harbour at Dusk gathers the cold blues and ochres of the northern evening into a single horizontal pulse. The boats are no more than strokes; the water is a ledger of every light that has crossed it. Brandt has said that she painted the harbour “until it forgave me,” and the surface carries that long negotiation in its layered glazes.' },
  { n: '13', artist: 'Tomas Ekwueme', life: '1938–2011', title: 'Study for a Monument', year: '1974', medium: 'charcoal and gouache on paper', dims: '76 × 56 cm (30 × 22 in.)', sign: 'signed and dated lower right', est: '£15,000 – 20,000', prov: ['The artist’s estate', 'Anon. sale, London, 2014, lot 41'], lit: 'T. Ekwueme: Drawings 1960–1985, Lagos, 2016, no. 112', essay: 'A preparatory drawing for the unrealised memorial that occupied Ekwueme through the 1970s, this sheet shows the forms at their most severe: a stack of rectangles leaning like a tide table. The gouache is laid on so thinly that the paper breathes through it.' },
  { n: '14', artist: 'Marguerite Dalle', life: 'b. 1974', title: 'Untitled (Weather)', year: '2012', medium: 'acrylic and graphite on linen', dims: '90 × 90 cm (35½ × 35½ in.)', sign: 'signed and dated on the stretcher', est: '£30,000 – 50,000', prov: ['Galerie Mercier, Paris', 'Private collection, Brussels'], lit: 'M. Dalle, Weather Reports, Paris, 2013, p. 40, illustrated', essay: 'Dalle’s grids are not drawn but weathered into being: she lets the linen sit outdoors for months before the paint is applied. The result is a surface that records its own history as faint rain tracks across a fixed geometry.' },
  { n: '15', artist: 'Oskar Winther', life: '1912–1988', title: 'Two Chairs', year: '1956', medium: 'oil on board', dims: '61 × 76 cm (24 × 30 in.)', sign: 'signed lower left', est: '£40,000 – 60,000', prov: ['The artist', 'Thence by descent'], lit: 'O. Winther, Catalogue Raisonné, Oslo, 1994, no. 318', essay: 'Winther painted the same two chairs for more than thirty years. In this version, one chair has turned to face the other, an event the artist described in his diary as “the great change of 1956.”' },
  { n: '16', artist: 'Nadia Farouk', life: 'b. 1983', title: 'Ice, 21:05', year: '2021', medium: 'archival pigment print, edition 2/5', dims: '100 × 150 cm (39¼ × 59 in.)', sign: 'signed, numbered and dated on a label on the reverse', est: '£6,000 – 9,000', prov: ['Galerie Quay, Edinburgh', 'Acquired from the above by the present owner'], lit: 'N. Farouk, Night Market, Edinburgh, 2022, plate 1', essay: 'From the artist’s Night Market series, Ice, 21:05 shows the first crate of the evening tipped into the trough at Quay Street. It is a picture about attention: the arc of the ice, a porter’s braced shoulder, the weight of cold.' },
  { n: '17', artist: 'Anselm Ode', life: 'b. 1968', title: 'The Wobble Chair', year: '1994', medium: 'ash, brass', dims: '84 × 42 × 44 cm (33 × 16½ × 17¼ in.)', sign: 'brass plate beneath the seat, inscribed “Mend me”', est: '£4,000 – 6,000', prov: ['The artist', 'Private collection, Leith'], lit: 'A. Ode, The Quiet Chair, Leith, 2026, pp. 12–19', essay: 'The first of the chairs Ode never allowed himself to repair: a plain ash dining chair with a left rear leg a quarter inch short. It has become, in the artist’s words, “the chair that reminds me who I work for.”' },
];
