export const DESIGNS_CB: Record<string, PublicationDesigner> = { 'cat-parts': parts, 'cat-auction': auction, 'cat-events': events };
export const LESSONS_CB: Record<string, DesignLesson> = {
  'cat-parts': { principle: 'A parts catalog is read with a finger: one order code per row, one column per attribute, and a rhythm of rules and zebra bands that lets the eye land on the right line without thinking.', history: 'Hardware catalogs grew out of the Victorian ironmongers’ price books and Sears-style wish books, then hardened into industrial reference works such as the McMaster-Carr and Grainger volumes. Their dense monospaced tables, exploded-view drawings and numbered callouts come straight from engineering drawing practice.', tryThis: 'Remove the zebra bands and measure how long it takes to find HB-10030. Put them back and measure again.', interestTag: 'Technical documents', related: ['Exploded views', 'Order codes', 'Data tables'] },
  'cat-auction': { principle: 'An auction catalog is a quiet machine for confidence: every lot gets the same ordered facts, in the same place, with an essay to justify the number.', history: 'Fine-art auction catalogues evolved from the printed sale notices of eighteenth-century London houses such as Christie’s and Sotheby’s into the scholarly, illustrated volumes of today. The sequence of lot number, artist, title, medium, dimensions, provenance, literature and estimate has barely changed, because collectors and scholars rely on it.', tryThis: 'Rewrite the catalogue note for lot 13 in 60 words without losing a single fact the reader would need to bid.', interestTag: 'Auction design', related: ['Provenance', 'Catalogue raisonné', 'Cormorant'] },
  'cat-events': { principle: 'A course catalog is a decision aid: colour sorts the subjects, a seats-left meter creates honest urgency, and the timetable lets a person see the week before they choose.', history: 'Adult-education prospectuses began with the evening classes of the mechanics’ institutes in the nineteenth century and the Workers’ Educational Association in 1903. Their modern descendants, from arts-centre term brochures to festival programmes, keep the same pairing of narrative course cards with a grid of days and times.', tryThis: 'Move one course in the timetable so it clashes with another and notice how fast the page tells you.', interestTag: 'Programme design', related: ['Timetables', 'Adult education', 'Wayfinding'] },
};
